import React, { forwardRef } from "react";
import { clsx } from "clsx";

import { TableClasses } from "../table.styles";

type TableFilterChipBarProps = {
  children: React.ReactNode;
  className?: string;
};

export const TableFilterChipBar = forwardRef<HTMLDivElement, TableFilterChipBarProps>(
  ({ children, className, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(TableClasses.filterChipBars, className)} {...props}>
        {children}
      </div>
    );
  },
);

TableFilterChipBar.displayName = "Table.FilterChipBars";
